sys_rte_eb_multi_in_script_operation.script:
(function(batch, output) {
   // Tenta departamentos Desenv 2, Desenv 1 e Gestor na seqüencia,
   // para garantir que seja preenchido com algum desses
   for (var i = 0; i < batch.length; i++) {
      var depNum = batch[i].input.split('|'); // Value of the input column.
      output[i] = '';
      depNum.forEach(function(dep) {
         if(dep){
            new global.GlideQuery('cmn_department')
            .where('id', dep)
            .where('u_active', true)
            .select(['id', "u_active", "name"])
            .forEach(function(dep) {
               output[i] = dep.sys_id;
            });
         }
      });
      if(output[i] == '') {
         depNum.forEach(function(dep) {
            if(dep){
               new global.GlideQuery('cmn_department')
               .where('id', dep)
               .select(['id', "u_active", "name"])
               .forEach(function(dep) {
                  output[i] = dep.sys_id;
               });
            }
         });
      }
   }
})(batch, output);
